"use client";

import { type CSSProperties, type HTMLAttributes, type ReactNode, type RefObject, useEffect, useRef } from "react";
import { createCursor, type CursorOptions } from "../interaction/cursor";
import { cx } from "../utils/cx";

export type CursorShape = "dot" | "ring" | "dot-ring" | "crosshair" | "icon" | "none";

export type CursorProps = Omit<CursorOptions, "scope"> & {
  /** What the cursor looks like. `icon` uses `icon` (and `icons`); `none` shows only the spotlight and trail. Default `dot`. */
  shape?: CursorShape;
  /** Your own cursor, centered on the pointer: an icon, an emoji, an image. Used with `shape="icon"`. */
  icon?: ReactNode;
  /** Icons for other states, replacing `icon` while the pointer is over a link or a text field. */
  icons?: { link?: ReactNode; text?: ReactNode };
  /** Dot (or crosshair) size in px. Default 8. */
  size?: number;
  /** Ring diameter in px. Default 38. */
  ringSize?: number;
  /** Any CSS color. Default: the strong text color. */
  color?: string;
  /** `difference` inverts what is under the cursor, so it stays visible on any background. */
  blend?: "normal" | "difference";
  /** A soft light that follows the cursor: `true` for the default, or its diameter in px. */
  spotlight?: boolean | number;
  /** A solid tail drawn along the path the cursor has taken (any number above 0 turns it on). */
  trail?: number;
  /** Keep the cursor inside this element instead of the whole page. */
  scope?: RefObject<HTMLElement | null>;
  className?: string;
};

/**
 * A custom cursor. It follows the pointer with an exponential ease (so it glides), changes with what is under it
 * (links, text fields, `data-hm-cursor` attributes), and can take any shape: a dot and a trailing ring, a crosshair,
 * or your own icon. Options add a magnetic pull and a ring that morphs to the shape of the button under it, squash and
 * an icon that turns to face where it is going, a spotlight, a trail and press ripples. It lives in
 * the top layer, above dialogs, hides the system cursor, and only runs for a mouse or pen: touch screens keep their
 * normal behavior. Decorative (hidden from assistive technology). Use `CursorArea` to keep it inside one region.
 */
export function Cursor({
  shape = "dot",
  icon,
  icons,
  size = 8,
  ringSize = 38,
  color,
  blend = "normal",
  spotlight = false,
  trail = 0,
  scope,
  className,
  smoothing,
  ringSmoothing,
  magnetic,
  morph,
  rotate,
  iconPoints,
  iconAnchors,
  trailWidth,
  hideNative,
  ripple,
  rippleSize,
  onStateChange,
}: CursorProps) {
  const root = useRef<HTMLDivElement>(null);
  const change = useRef(onStateChange);
  change.current = onStateChange;

  // biome-ignore lint/correctness/useExhaustiveDependencies: the engine is rebuilt when an option changes
  useEffect(() => {
    const el = root.current;
    if (!el) return;
    // the top layer: above dialogs and everything else. Where popovers are missing or fail, drop the attribute so the
    // fixed layer shows as plain markup (a hidden layer with a hidden system cursor would leave no pointer at all)
    let top = false;
    try {
      el.showPopover();
      top = true;
    } catch {
      el.removeAttribute("popover");
    }
    const handle = createCursor(el, {
      scope: scope?.current ?? null,
      smoothing,
      ringSmoothing,
      magnetic,
      morph,
      rotate,
      iconPoints,
      hideNative,
      ripple,
      rippleSize,
      onStateChange: (s) => change.current?.(s),
    });
    return () => {
      handle.destroy();
      if (top) {
        try {
          el.hidePopover();
        } catch {
          /* already gone */
        }
      }
    };
  }, [
    scope,
    shape,
    Boolean(spotlight),
    smoothing,
    ringSmoothing,
    magnetic,
    morph,
    rotate,
    iconPoints,
    hideNative,
    ripple,
    rippleSize,
    trail,
  ]);

  const style = {
    "--hm-cursor-dot": `${size}px`,
    "--hm-cursor-ring": `${ringSize}px`,
    "--hm-cursor-spot": typeof spotlight === "number" ? `${spotlight}px` : undefined,
    "--hm-cursor-color": color,
  } as CSSProperties;
  const showDot = shape === "dot" || shape === "dot-ring" || shape === "crosshair";
  const showRing = shape === "ring" || shape === "dot-ring";
  return (
    <div
      ref={root}
      popover="manual"
      aria-hidden="true"
      className={cx("hm-cursor", className)}
      data-shape={shape}
      data-blend={blend === "difference" ? "difference" : undefined}
      style={style}
    >
      {spotlight ? <span data-part="spot" /> : null}
      {trail > 0 ? (
        <svg
          data-part="trail"
          data-ms={60 + Math.min(8, trail) * 50}
          data-w={trailWidth ?? defaultTrailWidth(shape, size, ringSize)}
          aria-hidden="true"
          focusable="false"
        >
          <path />
        </svg>
      ) : null}
      {showRing ? (
        <span data-part="ring">
          <span data-part="label" />
        </span>
      ) : null}
      {showDot ? <span data-part="dot" /> : null}
      {shape === "icon" ? (
        <span data-part="icon">
          <span data-for="default" style={anchor(iconAnchors?.default)}>
            {icon}
          </span>
          {icons?.link ? (
            <span data-for="link" style={anchor(iconAnchors?.link ?? iconAnchors?.default)}>
              {icons.link}
            </span>
          ) : null}
          {icons?.text ? (
            <span data-for="text" style={anchor(iconAnchors?.text ?? iconAnchors?.default)}>
              {icons.text}
            </span>
          ) : null}
          <span data-part="label" />
        </span>
      ) : null}
    </div>
  );
}

/** The cursor's own width: a dot is as wide as the dot, a crosshair or ring is a thin line, an icon a medium stroke. */
function defaultTrailWidth(shape: CursorShape, size: number, ringSize: number) {
  if (shape === "crosshair") return 2;
  if (shape === "ring") return Math.max(2, Math.round(ringSize * 0.1));
  if (shape === "icon") return 5;
  return size;
}

const anchor = (a?: [number, number]) => (a ? ({ "--ax": a[0], "--ay": a[1] } as CSSProperties) : undefined);

export type CursorAreaProps = HTMLAttributes<HTMLDivElement> & CursorProps;

/** A region with its own cursor: the custom cursor shows (and the system cursor hides) only inside it. */
export function CursorArea({
  children,
  className,
  shape,
  icon,
  icons,
  size,
  ringSize,
  color,
  blend,
  spotlight,
  trail,
  smoothing,
  ringSmoothing,
  magnetic,
  morph,
  rotate,
  iconPoints,
  iconAnchors,
  trailWidth,
  hideNative,
  ripple,
  rippleSize,
  onStateChange,
  ...rest
}: CursorAreaProps) {
  const area = useRef<HTMLDivElement>(null);
  return (
    <div {...rest} ref={area} className={cx("hm-cursor-area", className)}>
      <Cursor
        scope={area}
        shape={shape}
        icon={icon}
        icons={icons}
        size={size}
        ringSize={ringSize}
        color={color}
        blend={blend}
        spotlight={spotlight}
        trail={trail}
        smoothing={smoothing}
        ringSmoothing={ringSmoothing}
        magnetic={magnetic}
        morph={morph}
        rotate={rotate}
        iconPoints={iconPoints}
        iconAnchors={iconAnchors}
        trailWidth={trailWidth}
        hideNative={hideNative}
        ripple={ripple}
        rippleSize={rippleSize}
        onStateChange={onStateChange}
      />
      {children}
    </div>
  );
}
